// 組 Gemini 提示與回應 schema（完整版見 n8n/gemini-prompt.md）
const p = $('Parse LINE Event').item.json;
const prompt = [
  '你是營養估算助手。根據餐點照片與使用者備註，逐項列出食物、推估份量(克)與三大營養素。',
  '規則：1) 每項給 assumed portion_g 與 0-1 信心度；2) 不確定就給區間中點並降低信心度；',
  '3) 只輸出 JSON，不要解釋。',
  '使用者備註：' + (p.text || '（無）')
].join('\n');
const schema = {
  type: 'object',
  properties: {
    items: { type: 'array', items: { type: 'object', properties: {
      name: { type: 'string' }, portion_g: { type: 'number' }, portion_confidence: { type: 'number' },
      carb_g: { type: 'number' }, net_carb_g: { type: 'number' }, protein_g: { type: 'number' },
      fat_g: { type: 'number' }, fiber_g: { type: 'number' }
    }, required: ['name','portion_g','carb_g','protein_g','fat_g'] } },
    totals: { type: 'object', properties: {
      carb_g: { type: 'number' }, net_carb_g: { type: 'number' }, protein_g: { type: 'number' },
      fat_g: { type: 'number' }, fiber_g: { type: 'number' } } },
    gi_est: { type: 'number' }, gl_est: { type: 'number' }, gi_confidence: { type: 'number' },
    eating_order: { type: 'string', enum: ['veg_first','carb_first','mixed','unknown'] },
    post_meal_activity: { type: 'string', enum: ['none','walk_10_15min','walk_30min+','unknown'] }
  },
  required: ['items','totals']
};
return [{ json: { prompt, schema } }];

// 解析 Gemini 回應 → 套用個人常吃食物表覆蓋總碳水 → 組 meals 列
const p = $('Parse LINE Event').item.json;
const resp = $input.first().json;
let est = {};
try {
  est = JSON.parse(resp.candidates[0].content.parts[0].text);
} catch (e) {
  est = { items: [], totals: {}, _parse_error: String(e) };
}

// TODO: 從 Google Sheets 讀 personal_food_table，對 est.items[].name 做碳水覆蓋
// const table = $('Load Personal Food Table').all(); ...
const PERSONAL_TABLE = {}; // { '白飯(半碗)': { carb_per_100g: 37 }, ... }

function round1(x) { return x == null ? null : Math.round(x * 10) / 10; }
const totals = est.totals || {};
const confidences = (est.items || []).map(i => i.portion_confidence).filter(x => typeof x === 'number');
const confidence = confidences.length ? round1(confidences.reduce((a,b)=>a+b,0)/confidences.length) : 0.4;

return [{ json: {
  meal_id: p.t0,
  t0: p.t0,
  note: p.text || '',
  items_json: JSON.stringify(est.items || []),
  carb_g: round1(totals.carb_g),
  net_carb_g: round1(totals.net_carb_g ?? totals.carb_g),
  protein_g: round1(totals.protein_g),
  fat_g: round1(totals.fat_g),
  fiber_g: round1(totals.fiber_g),
  gi_est: round1(est.gi_est),
  gl_est: round1(est.gl_est),
  eating_order: est.eating_order || 'unknown',
  post_meal_activity: est.post_meal_activity || 'unknown',
  confidence,
  user_confirmed: false,
  image_url: ($('Archive Image to Drive').item.json.webViewLink) || '',
  source_user: p.source_user
} }];

